import fs from 'node:fs/promises';
import path from 'node:path';
const [base='http://127.0.0.1:9471',siteDir='outputs/site',output='outputs/browser-layout/interactions.json']=process.argv.slice(2);
const info=JSON.parse(await fs.readFile(path.join(siteDir,'build-info.json'),'utf8'));
const source=await fs.readFile(new URL(import.meta.url),'utf8');
const version=await (await fetch('http://127.0.0.1:9233/json/version')).json();
const socket=new WebSocket(version.webSocketDebuggerUrl);
await new Promise((r,j)=>{socket.onopen=r;socket.onerror=j});let id=0;const waiting=new Map();
socket.onmessage=e=>{const x=JSON.parse(e.data);if(x.id){const p=waiting.get(x.id);waiting.delete(x.id);x.error?p.reject(new Error(JSON.stringify(x.error))):p.resolve(x.result)}};
function call(method,params={},sessionId){const n=++id;return new Promise((resolve,reject)=>{waiting.set(n,{resolve,reject});socket.send(JSON.stringify({id:n,method,params,...(sessionId?{sessionId}:{})}))})}
const {targetId}=await call('Target.createTarget',{url:'about:blank'});
const records=[];
try{
 const {sessionId}=await call('Target.attachToTarget',{targetId,flatten:true});
 const page=(method,params={})=>call(method,params,sessionId);
 async function evaluate(expression){const x=await page('Runtime.evaluate',{expression,awaitPromise:true,returnByValue:true});if(x.exceptionDetails)throw new Error(JSON.stringify(x.exceptionDetails));return x.result.value}
 async function until(expression,description){for(let i=0;i<150;i++){if(await evaluate(expression))return;await new Promise(r=>setTimeout(r,100))}throw new Error('Timed out: '+description)}
 async function navigate(name){const r=await page('Page.navigate',{url:base+'/'+name+'?interact='+Date.now()});if(r.errorText)throw new Error(r.errorText);await until(`document.readyState==='complete' && decodeURIComponent(location.pathname).endsWith(${JSON.stringify('/'+name)})`,'page ready');await evaluate('document.fonts.ready.then(()=>true)')}
 await page('Page.enable');await page('Network.enable');await page('Network.setCacheDisabled',{cacheDisabled:true});
 for(const width of [1440,390]){
  await page('Emulation.setDeviceMetricsOverride',{width,height:1000,deviceScaleFactor:1,mobile:width<600});
  await navigate('1.1.html');
  await until(`!!document.querySelector('.diagram-zoom') && !document.querySelector('.diagram-zoom').hidden`,'diagram control initialized');
  const original=await evaluate(`(()=>{const main=document.querySelector('.md-typeset'),f=document.querySelector('.illustration'),i=f.querySelector('img');return {main_width:main.getBoundingClientRect().width,figure_width:f.getBoundingClientRect().width,image_width:i.getBoundingClientRect().width,body_font:getComputedStyle(main).fontSize,document_width:document.documentElement.scrollWidth,viewport:innerWidth}})()`);
  if(Math.abs(original.figure_width-original.main_width)>1||Math.abs(original.image_width-original.main_width)>1)throw new Error('Default diagram does not fill text column');
  const zoom=await evaluate(`(()=>{const b=document.querySelector('.diagram-zoom');b.click();const v=document.getElementById(b.getAttribute('aria-controls'));const r={expanded:b.getAttribute('aria-expanded'),class_expanded:v.classList.contains('is-enlarged'),viewport_width:v.clientWidth,scroll_width:v.scrollWidth,document_width:document.documentElement.scrollWidth};b.click();r.restored=b.getAttribute('aria-expanded')==='false'&&!v.classList.contains('is-enlarged');return r})()`);
  if(zoom.expanded!=='true'||!zoom.class_expanded||!zoom.restored||zoom.document_width>width+1||zoom.scroll_width<800)throw new Error('Diagram zoom interaction failed');
  const download=await evaluate(`(async()=>{const a=[...document.querySelectorAll('.md-typeset a')].find(a=>a.hasAttribute('download')&&a.getAttribute('href')?.endsWith('.ipynb'));if(!a)throw new Error('No download link');const r=await fetch(a.href);if(!r.ok)throw new Error('Download HTTP '+r.status);const n=await r.json();return {href:a.getAttribute('href'),http_status:r.status,lesson_id:n.metadata.lesson_id,code_cells:n.cells.filter(c=>c.cell_type==='code').length,colab:[...document.querySelectorAll('.md-typeset a')].filter(a=>a.href.startsWith('https://colab.research.google.com/')).map(a=>a.href)}})()`);
  if(download.lesson_id!=='1.1'||!download.code_cells||!download.colab.length||download.colab.some(u=>!u.includes('/blob/'+info.revision+'/notebooks/01/1.1.ipynb')))throw new Error('Download or pinned Colab link differs from generated source');
  const warmup=await evaluate(`(()=>{const a=[...document.querySelectorAll('.md-typeset a')].find(a=>a.getAttribute('href')?.includes('first-steps.html#W.2'));if(!a)throw new Error('Missing direct W.2 prerequisite');const href=a.href;a.click();return href})()`);
  await until(`location.pathname.endsWith('/first-steps.html') && decodeURIComponent(location.hash)==='#W.2' && !!document.getElementById('W.2')`,'warmup jump');
  const target=await evaluate(`({url:location.href,heading:document.getElementById('W.2').textContent,has_program:document.querySelectorAll('.md-typeset .language-python').length>0})`);
  if(!target.heading.includes('W.2')||!target.has_program)throw new Error('Warmup content missing');
  await navigate('1.1.html');
  await until(`!!document.querySelector('.md-search__button')`,'search button');
  await evaluate(`document.querySelector('.md-search__button').click()`);
  await until(`[...document.querySelectorAll('*')].some(e=>e.shadowRoot?.querySelector('input[role=combobox]'))`,'shadow search input');
  const searches=[];
  for(const query of ['Flash','量化']){
   await evaluate(`(()=>{const root=[...document.querySelectorAll('*')].find(e=>e.shadowRoot?.querySelector('input[role=combobox]')).shadowRoot;const input=root.querySelector('input[role=combobox]');input.focus();input.value='';input.dispatchEvent(new Event('input',{bubbles:true,composed:true}));})()`);
   await page('Input.insertText',{text:query});
   await until(`(()=>{const root=[...document.querySelectorAll('*')].find(e=>e.shadowRoot?.querySelector('input[role=combobox]')).shadowRoot;const links=[...root.querySelectorAll('a')];return root.querySelector('input').value===${JSON.stringify(query)}&&links.length>0&&links.every(a=>new URL(a.href).searchParams.get('h')===${JSON.stringify(query)})})()`,'search results for '+query);
   const result=await evaluate(`(()=>{const root=[...document.querySelectorAll('*')].find(e=>e.shadowRoot?.querySelector('input[role=combobox]')).shadowRoot;return {query:root.querySelector('input').value,links:[...root.querySelectorAll('a')].map(a=>({href:a.href,title:a.querySelector('h2')?.textContent||a.textContent.slice(0,120)}))}})()`);
   const expected=query==='Flash'?/\/16\.9\.html/:/\/17\.\d+\.html/;
   if(!result.links.some(a=>expected.test(new URL(a.href).pathname)))throw new Error('Search does not include a relevant lesson: '+query);
   searches.push(result);
  }
  records.push({width,default_diagram:original,zoom,download,warmup:{clicked_href:warmup,target},searches});
 }
 const report={schema_version:1,status:'passed',checked_at:new Date().toISOString(),scope:'Actual Chromium interaction on desktop and mobile emulation: default figure sizing, diagram zoom/reset, direct prerequisite jump, fetching the lesson notebook, pinned Colab link inspection and typed Shadow DOM search. It does not execute Colab remotely or establish that tiny models answer correctly.',browser:version.Browser,build_info:info,verification_program:source,records};
 await fs.mkdir(path.dirname(output),{recursive:true});await fs.writeFile(output,JSON.stringify(report,null,2)+'\n');
 console.log(JSON.stringify({status:report.status,viewports:records.map(r=>r.width),searches:records.map(r=>r.searches.map(s=>({query:s.query,results:s.links.length}))),output}));
}finally{await call('Target.closeTarget',{targetId});socket.close()}
